def _norm(numero):
    if not numero:
        return numero
    dig = "".join(c for c in str(numero) if c.isdigit())
    while dig.startswith("5151") and len(dig) > 11:
        dig = dig[2:]
    if len(dig) == 9 and dig.startswith("9"):
        dig = "51" + dig
    if len(dig) == 11 and dig.startswith("51"):
        return dig
    return str(numero).strip()


def normalizar(apps, schema_editor):
    Mensaje = apps.get_model("whatsapp", "MensajeWhatsApp")
    Cita = apps.get_model("whatsapp", "CitaWhatsApp")
    Conv = apps.get_model("whatsapp", "ConversacionWhatsApp")

    for Modelo in (Mensaje, Cita):
        cambios = []
        for obj in Modelo.objects.only("id", "numero").iterator():
            nuevo = _norm(obj.numero)
            if nuevo != obj.numero:
                obj.numero = nuevo
                cambios.append(obj)
        Modelo.objects.bulk_update(cambios, ["numero"], batch_size=500)

    # Conversaciones: el número es único. Si existe la versión con y sin 51,
    # se conserva la que tuvo actividad más reciente.
    por_numero = {}
    for c in Conv.objects.all().order_by("-actualizado"):
        por_numero.setdefault(_norm(c.numero), []).append(c)
    for numero, convs in por_numero.items():
        quedar, sobran = convs[0], convs[1:]
        for c in sobran:
            c.delete()
        if quedar.numero != numero:
            Conv.objects.filter(pk=quedar.pk).update(numero=numero)

    Conv.objects.filter(estado_desde__isnull=True).update(estado_desde=models.F("actualizado"))


